282	\section{The Pauli basis test}
283	% Paper label sec:qld-game kept for cross-reference fidelity.
284	\label{sec:qld-game}
285

380			\item (\textbf{Commutation check}) If $t_w = (\mathsf{Pair},W)$ and $t_{\overline w} = \mathsf{Pair}$, accept if $a_w = \beta_W$ or $\gamma \neq 0$.
381			\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{Pair},W)$, accept if $\tr(a_w r_W) = a_{\overline w}$ or $\gamma \neq 0$.
382			\item (\textbf{Magic Square check}) If $t_w = \mathsf{Constraint}_i$ and $t_{\overline w} = \mathsf{Variable}_j$, accept if $\gamma = 0$, or if $a_w$ satisfies the equation of $\mathsf{Constraint}_i$ and $\alpha_j = a_{\overline w}$.
383			\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = \mathsf{Variable}_j$, accept if $\gamma = 0$, or if $j = 1$, $W = X$, and $\tr(a_w r_X) = a_{\overline w}$, or if $j = 5$, $W = Z$, and $\tr(a_w r_Z) = a_{\overline w}$.
384		\end{enumerate}
385		The game $\mathfrak{G}^{\mathrm{Pauli}}_{\mathsf{qldparams}}$ is the typed game with type set $\mathcal T^{\mathrm{pauli}}$, the question distribution of Definition~\ref{def:pauli-question-distribution}, and win predicate $D^{\mathrm{pauli}}_{\mathsf{qldparams}}$.
386	\end{definition}
387	
388	Note the one-sided gating on $\gamma$: the commutation check and the $\mathsf{Pair}$ consistency check accept automatically when $\gamma \neq 0$, while the Magic Square check and the $\mathsf{Variable}$ consistency check accept automatically when $\gamma = 0$.
389	
390	\begin{lemma}[Completeness of the Pauli basis test]\label{lem:pauli-completeness}
391		\lean{MIPStarRE.QPBT.pauliBasisTestSymm, MIPStarRE.QPBT.exists_spcc_value_one}
392		\leanok
393		\uses{def:pauli-question-distribution, def:pauli-win-predicate, def:admissible, def:spcc, def:tensor-product-value}
394		For every admissible tuple $\mathsf{qldparams} = (q,m,d)$ (Definition~\ref{def:admissible}), the Pauli basis test $\mathfrak{G}^{\mathrm{Pauli}}_{\mathsf{qldparams}}$ has a value-$1$ SPCC strategy.
395	\end{lemma}
396	\begin{proof}
397		\uses{thm:ms-from-ac, def:pauli-win-predicate, def:bracket, def:consistent-measurement, def:EPR, def:indicator-vector, lem:pauli-observable-expansion, lem:twisted-commutation}
398		The strategy uses the state $\ket{\psi} = \ket{\mathrm{EPR}_q}^{\ot M} \ot \ket{\mathrm{EPR}_2}$ with $M = 2^m$. On a question $((\mathsf{Point},W), y)$ a player measures the generalized Pauli basis POVM $\{\tau^W_h\}_{h \in \F_q^M}$ and reports $g_h(y)$; on $((\mathsf{ALine},W), \ell)$ or $((\mathsf{DLine},W), \ell)$ they report the restriction of $g_h$ to the line $\ell$, expressed as a univariate polynomial through the canonical parameterization of $\ell$; and on $(\mathsf{Pauli},W)$ they report $h$ itself --- in the bracket notation of Definition~\ref{def:bracket}, these measurements are $\tau^W_{[g_\cdot(y) = a]} \ot I$, $\tau^W_{[(g_\cdot)|_\ell = f]} \ot I$, and $\tau^W_a \ot I$. For a content $\omega = (u_X, u_Z, r_X, r_Z)$, consider the two binary measurements $A_b = \tau^X_{[\tr(g_\cdot(u_X)\, r_X) = b]} \ot I$ and $B_b = \tau^Z_{[\tr(g_\cdot(u_Z)\, r_Z) = b]} \ot I$. Since $g_h(u) = h \cdot \mathrm{ind}_m(u)$ (Chapter~\ref{chap:qpbt-algebra}), the relation between the Pauli projections and observables gives $\mathcal O_A = A_0 - A_1 = \tau^X(\mathrm{ind}_m(u_X)\, r_X) \ot I$ and $\mathcal O_B = \tau^Z(\mathrm{ind}_m(u_Z)\, r_Z) \ot I$, and the twisted commutation relation yields
399		\[
400			\mathcal O_A \mathcal O_B = (-1)^\gamma\, \mathcal O_B \mathcal O_A
401		\]
402		with $\gamma$ as in Equation~\eqref{eq:gamma-value}: the two measurements commute when $\gamma = 0$ and anticommute when $\gamma = 1$. If $\gamma = 0$, define $E^{\mathsf{Pair},\omega}_{\beta_X,\beta_Z} = A_{\beta_X} B_{\beta_Z}$ and $E^{(\mathsf{Pair},X),\omega}_a = A_a$, $E^{(\mathsf{Pair},Z),\omega}_a = B_a$, and let the $\mathsf{Constraint}$ and $\mathsf{Variable}$ measurements be trivial (identity on the all-zeros outcome). If $\gamma = 1$, let the $\mathsf{Constraint}$ and $\mathsf{Variable}$ measurements be those produced by Theorem~\ref{thm:ms-from-ac} from the anticommuting consistent pair $(A, B)$, acting on the auxiliary $\ket{\mathrm{EPR}_2}$ factor, and let the $\mathsf{Pair}$ measurements be trivial. The strategy is symmetric and projective by construction; every measurement is either a post-processed Pauli basis measurement, a measurement supplied by Theorem~\ref{thm:ms-from-ac}, or (in the $\gamma = 0$ case) a product of two commuting consistent measurements, so the strategy is consistent, and commutativity along every edge of $G^{\mathrm{pauli}}$ is checked case by case --- for instance, $(\mathsf{Point},X)$ and $\mathsf{Variable}_1$ commute because both are $X$-basis measurements. Consistency and projectivity give the consistency checks with certainty, and the low-degree checks pass because the answers agree with the strategy determined by the polynomial $g_h$ in the classical game. For the remaining checks: when $\gamma = 0$ the commutation check passes by construction, and when $\gamma = 1$ the Magic Square check passes by Theorem~\ref{thm:ms-from-ac}; the consistency checks 5 and 7 pass with certainty because $\tau^W_{[\tr(g_\cdot(y)\, r_W) = \cdot]} \ot I$ coincides with $E^{(\mathsf{Pair},W),\omega}$, respectively with the embedded $\mathsf{Variable}_1$ and $\mathsf{Variable}_5$ measurements of Theorem~\ref{thm:ms-from-ac} (item~3 there). Hence the strategy has value $1$.
403	\end{proof}
