468	
469	We specify a canonical setting of the parameter tuple $\mathsf{qldparams}$ as a function of an integer $R$, and bound the resulting soundness function. All logarithms are base $2$.
470	
471	\begin{definition}[Canonical parameters of the Pauli basis test]\label{def:introparams}
472		\lean{MIPStarRE.QPBT.introParamsC, MIPStarRE.QPBT.introParamsTuple, MIPStarRE.QPBT.AdmissibleParams.ofTuple, MIPStarRE.QPBT.introParams}
473		\leanok
474		\uses{thm:pauli}
475		Let $a, b$ be the universal constants of Theorem~\ref{thm:pauli}, and let $c$ be the smallest \emph{even} integer that is at least $(b+a)/b$. For every integer $R \ge 4$, define the tuple $\mathsf{introparams}(R) = (q, m, d)$ by
476		\begin{itemize}
477			\item $q = 2^k$ for $k = c \lceil \log \log R \rceil + 1$,
478			\item $m = 2^j$, where $j$ is the unique integer with $2^j \le c \lceil \log R \rceil + 1 < 2^{j+1}$,
479			\item $d = 1$.
480		\end{itemize}
481		The letter $k$ here denotes the exponent of the field size and is unrelated to the simultaneity parameter $k$ of the classical game. With this choice the Pauli basis test certifies the presence of an $M = 2^m$-qudit maximally entangled state of local dimension $q$, equivalently an $(M \log q)$-qubit EPR state, and the choice $d = 1$ runs the low individual degree test multilinearly.
482	\end{definition}
483	
484	\begin{lemma}[Soundness bound for the canonical parameters]\label{lem:delta-bound}
485		\lean{MIPStarRE.QPBT.introParamsTuple_isAdmissible, MIPStarRE.QPBT.le_two_pow_introParams_m, MIPStarRE.QPBT.exists_deltaQld_introParams_bound}
486		\leanok
487		\uses{def:introparams, def:admissible, thm:pauli}
488		For all integers $R \ge 4$, the parameter tuple $\mathsf{introparams}(R) = (q,m,d)$ is admissible (Definition~\ref{def:admissible}) and satisfies $2^m \ge R$. Furthermore, there exist universal constants $a' \ge 1$ and $0 < b' \le 1$ such that the function $\delta_{\mathrm{qld}}(\eps, m, d, q)$ of Theorem~\ref{thm:pauli} is at most
489		\[
490			a' \bigl( (\log R)^{a'} \cdot \eps^{b'} + (\log R)^{-b'} \bigr)\;.
491		\]
492	\end{lemma}
493	\begin{proof}
494		\uses{def:introparams, def:admissible, def:admissible-size, thm:pauli}
495		Since $c$ is even, the exponent $k = c \lceil \log\log R \rceil + 1$ is odd, so $q = 2^k$ is an admissible field size; $m$ divides $q$ because $2^j \le c \lceil \log R \rceil + 1 \le 2 \log^c R \le 2^k$, so $j \le k$ and both are powers of $2$; and $d = 1 \ge 1$. Hence the tuple is admissible. Since $m = 2^j \ge (c/2) \log R$, we get $2^m \ge R^{c/2} \ge R$, using $c \ge 2$.
496	
497		For the soundness bound, write $\delta_{\mathrm{qld}}(\eps,m,d,q) = a(md)^a \eps^b + a(md)^a q^{-b} + a(md)^a 2^{-bmd}$ and use $d = 1$, $m \le 2c \log R$, and $q = 2^k \ge \log^c R$. The first term is at most $a(2c)^a (\log R)^a \eps^b$. The second term is at most $a(2c)^a (\log R)^{a - cb} \le a(2c)^a (\log R)^{-b}$, since $cb - a \ge b$ by the choice of $c$. For the third term, $m \ge (c/2) \log R \ge \log R$ gives $2^{-bm} \le R^{-b}$, so
498		\[
499			a(md)^a\, 2^{-bm}
500			\le a(2c)^a (\log R)^a R^{-b}
501			= a(2c)^a \bigl( (\log R)^{a+b} R^{-b} \bigr) (\log R)^{-b}
502			\le a(2c)^a\, C\, (\log R)^{-b}\;,
503		\]
504		where $C = \sup_{R' \ge 4} (\log R')^{a+b} (R')^{-b}$ is finite --- the function is continuous in $R'$ and tends to $0$ as $R' \to \infty$ --- and depends only on the universal constants $a$ and $b$. Summing the three bounds, the statement follows with $a' = a(2c)^a (1 + C)$ and $b' = b$.
505	\end{proof}
506	
507	\begin{remark}[A comparison of exponents in the source proof of Lemma~\ref{lem:delta-bound}]\label{rem:delta-bound-exponent-comparison}
508		The source proof bounds the third term of $\delta_{\mathrm{qld}}$ by asserting $2^{-bmd} \le q^{-b}$ ``because $k \le m$'', comparing the field exponent $k = c \lceil \log\log R \rceil + 1$ with $m = 2^j$. The inequality $k \le m$ does not follow from Definition~\ref{def:introparams}: if the universal constants of Theorem~\ref{thm:pauli} were $a = 1$ and $b = 1/2$, then $c = 4$, and $R = 5$ gives $k = 9$ and $m = 8$. The proof above instead bounds $2^{-bm} \le R^{-b}$ directly from $m \ge (c/2) \log R \ge \log R$, which yields the same conclusion after enlarging the universal constant $a'$.
509	\end{remark}

