457	\section{Lines}
458	
459	The question distributions of the classical low individual degree game and of
460	the Pauli basis test (Chapter~\ref{chap:qpbt-test}) sample lines in $\F_q^m$;
461	we record here the definition of lines and their canonical representatives.
462	
463	\begin{definition}[Lines]\label{def:line}
464		A \emph{line} $\ell$ in $\F_q^m$ specified by a pair
465		$(u,v) \in (\F_q^m)^2$ is the subset
466		\begin{equation}\label{eq:line-set}
467			\ell(u,v) = \bigl\{\, u + tv : t \in \F_q \,\bigr\} \subseteq \F_q^m\;.
468		\end{equation}
469		The vector $v$ is called a \emph{direction} of $\ell(u,v)$; the case $v = 0$
470		is explicitly allowed, in which case the line is the singleton $\{u\}$. A
471		line $\ell(u,v)$ is \emph{axis-parallel} if there is a coordinate
472		$i \in \{1, \dots, m\}$ for which $v = e_i$, the $i$-th elementary basis
473		vector of $\F_q^m$; such a line is said to be \emph{parallel to the $i$-th
474		direction}. A line $\ell(u,v)$ is \emph{diagonal} if there exists
475		$i \in \{0, 1, \dots, m-1\}$ such that $v_1 = v_2 = \dots = v_i = 0$ (for
476		$i = 0$ the condition is vacuous, so every line is diagonal).
477	\end{definition}
478	
479	\begin{proposition}\label{prop:line-equiv}
480		\uses{def:line}
481		Let $u, v \in \F_q^m$. Then for all $u' \in \ell(u,v)$, we have
482		$\ell(u,v) = \ell(u',v)$.
483	\end{proposition}
484	\begin{proof}
485		\uses{def:line}
486		Fix $u' \in \ell(u,v)$, so $u' = u + tv$ for some $t \in \F_q$. Any
487		$a \in \ell(u,v)$ has the form $a = u + sv = u' + (s - t)v$, so
488		$\ell(u,v) \subseteq \ell(u',v)$. The symmetric argument gives the reverse
489		inclusion.
490	\end{proof}
491	
492	Thus, for a fixed direction, a line is an equivalence class of its points: the
493	pair $(u,v)$ representing it can use any base point on the line. A canonical
494	representation is obtained as follows.
495	
496	\begin{definition}[Canonical representative of a line]\label{def:line-representative}
497		\uses{def:line, def:cl-canonical, prop:line-equiv}
498		Let $\ell$ be a line in direction $v \neq 0$, and let
499		$L^{\mathrm{Ln}}_v : \F_q^m \to \F_q^m$ denote the canonical linear map with
500		the one-dimensional kernel basis $\{v\}$
501		(Definition~\ref{def:cl-canonical}). The \emph{canonical representative of
502		$\ell$} is the point $u_0 \in \F_q^m$ such that
503		\[
504			u_0 = L^{\mathrm{Ln}}_v(u) \qquad \text{for all } u \in \ell\;.
505		\]
506		This is well defined: since the image and kernel of $L^{\mathrm{Ln}}_v$ are
507		complementary, any $u \in \ell$ decomposes uniquely as $u = u_0 + tv$ with
508		$u_0$ in the image, so $u_0 = u - tv \in \ell$ and
509		$L^{\mathrm{Ln}}_v(u_0) = u_0$; moreover any two points of $\ell$ differ by
510		a multiple of $v$ and therefore have the same image under
511		$L^{\mathrm{Ln}}_v$. A line $\ell = \ell(u,v)$ is henceforth canonically
512		represented by the pair $(u_0, v)$. (For $v = 0$, where the singleton
513		$\{u\}$ leaves no independent kernel basis, we take $L^{\mathrm{Ln}}_0$ to
514		be the identity---the canonical linear map with empty kernel basis---so
515		that $u_0 = u$; the source leaves this case implicit.)
516	\end{definition}
517	
518	\section{Quantum registers and EPR states}
519	% Paper label sec:lin-reg kept for cross-reference fidelity.
520	\label{sec:lin-reg}
521	
522	\begin{definition}[State space of a linear register]\label{def:lin-reg}
523		\uses{def:complementary}
524		For a set $V$, we write $\C^V$ for the complex vector space of dimension
525		$|V|$, endowed with the canonical orthonormal basis
526		$\{\ket{x}\}_{x \in V}$. A \emph{quantum state on $V$} is a unit vector
527		$\ket{\psi}_V \in \C^V$. If $V = \bigoplus_{i=1}^k V_i$ is a direct sum of
528		subspaces over $\F$, then $\C^V$ is identified with
529		$\bigotimes_{i=1}^k \C^{V_i}$ by identifying
530		$\ket{x_1 \oplus \dots \oplus x_k}$ with
531		$\ket{x_1} \ot \dots \ot \ket{x_k}$. In particular, a basis $\{e_i\}$ of
532		$V$ yields the decomposition $V = \bigoplus_{i=1}^k (\F e_i)$ and hence
533		$\C^V = \bigotimes_{i=1}^k \C^{|\F|}$; the factors $\C^{|\F|}$ are called
534		the \emph{qudits} of $\C^V$.
535	\end{definition}
536	
537	\begin{definition}[EPR state]\label{def:EPR}
538		\uses{def:lin-reg}
539		For a linear space $V$ over a finite field $\F$, the \emph{EPR state} on
540		$\C^V \ot \C^V$ is
541		\[
542			\ket{\mathrm{EPR}}_V
543			= \frac{1}{\sqrt{|V|}} \sum_{x \in V} \ket{x} \ot \ket{x}\;.
544		\]
545		We write $\ket{\mathrm{EPR}_q}$ for $\ket{\mathrm{EPR}}_{\F_q}$ and
546		$\ket{\mathrm{EPR}}$ for $\ket{\mathrm{EPR}_2}$.
547	\end{definition}
