549	\section{Generalized Pauli observables}
550	% Paper label sec:generalized-pauli kept for cross-reference fidelity.
551	\label{sec:generalized-pauli}
552	
553	\begin{definition}[Generalized Pauli observables]\label{def:generalized-pauli}
554		\lean{MIPStarRE.QPBT.primeTauShift, MIPStarRE.QPBT.primeTauPhase}
555		\lean{MIPStarRE.QPBT.primeTauObservable}
556		\uses{def:subfield-trace, def:lin-reg}
557		Let $p$ be a prime and $\omega = e^{2\pi i/p}$. The \emph{generalized Pauli
558		observables over $\F_p$} are the unitaries on $\C^{\F_p}$ given by
559		\begin{equation}\label{eq:pauli-fp}
560			\sigma^X(a) = \sum_{j \in \F_p} \ket{j + a}\bra{j}
561			\qquad \text{and} \qquad
562			\sigma^Z(b) = \sum_{j \in \F_p} \omega^{bj} \ket{j}\bra{j}
563		\end{equation}
564		for $a, b \in \F_p$, with arithmetic over $\F_p$. For $q = p^k$, the
565		\emph{generalized Pauli observables over $\F_q$} are the unitaries on
566		$\C^{\F_q}$
567		\[
568			\tau^X(a) = \sum_{j \in \F_q} \ket{j + a}\bra{j}
569			\qquad \text{and} \qquad
570			\tau^Z(b) = \sum_{j \in \F_q} \omega^{\tr(bj)} \ket{j}\bra{j}
571		\]
572		for $a, b \in \F_q$, where $\tr$ here denotes $\tr_{q \to p}$
573		(Definition~\ref{def:subfield-trace}); for admissible $q$ this agrees with
574		the standing shorthand, $p = 2$, and $\omega = -1$, so that all phases are
575		signs. All the $\tau^X$ operators commute with one another, as do all the
576		$\tau^Z$ operators. Their common eigenbases consist of the vectors
577		$\ket{e_W}$, labeled by $e \in \F_q$ and $W \in \{X, Z\}$, given by
578		\[
579			\ket{e_X} = \frac{1}{\sqrt{q}} \sum_{j \in \F_q}
580			\omega^{-\tr(ej)} \ket{j}\;, \qquad
581			\ket{e_Z} = \ket{e}\;;
582		\]
583		the Fourier transform
584		\begin{equation}\label{eq:fourier-f}
585			F = \frac{1}{\sqrt{q}} \sum_{a, b \in \F_q}
586			\omega^{-\tr(ab)} \ket{a}\bra{b}
587		\end{equation}
588		maps the computational ($Z$) eigenbasis to the $X$ eigenbasis. We write
589		$\{\tau^W_e\}_{e \in \F_q}$ for the projective measurement whose elements
590		are the rank-one projectors onto the vectors of the $W$ eigenbasis. For
591		systems of $n$ qudits, we write, for $W \in \{X,Z\}$ and $a \in \F_q^n$,
592		\[
593			\tau^W(a) = \tau^W(a_1) \ot \dots \ot \tau^W(a_n)\;, \qquad
594			\ket{e_W} = \ket{(e_1)_W} \ot \dots \ot \ket{(e_n)_W}
595		\]
596		for $e \in \F_q^n$, with associated rank-one projectors $\tau^W_e$.
597	\end{definition}
598	
599	\begin{lemma}[Product and twisted commutation relations]\label{lem:twisted-commutation}
600		\lean{MIPStarRE.QPBT.primeTauObservable_mul}
601		\lean{MIPStarRE.QPBT.primeTauObservable_pow}
602		\lean{MIPStarRE.QPBT.primeTauObservable_pow_char}
603		\lean{MIPStarRE.QPBT.primeTauObservable_isUnitary}
604		\lean{MIPStarRE.QPBT.primeTauObservable_eigenvalue_pow_char}
605		\lean{MIPStarRE.QPBT.primeTauObservable_X_mul_Z}
606		\leanok
607		\uses{def:generalized-pauli, def:subfield-trace, def:dot-product-orthogonal}
608		Let $q = p^k$, let $n \ge 1$ be an integer, and let $W \in \{X, Z\}$.
609		\begin{enumerate}
610			\item For all $a, a' \in \F_q$ and $b \in \F_p$,
611			      \begin{equation}\label{eq:pauli-product-power}
612				      \tau^W(a)\, \tau^W(a') = \tau^W(a + a')
613				      \qquad \text{and} \qquad
614				      \bigl(\tau^W(a)\bigr)^b = \tau^W(ab)\;;
615			      \end{equation}
616			      in particular $\bigl(\tau^W(a)\bigr)^p = \Id$. By the explicit
617			      definitions each $\tau^W(a)$ is unitary, and its eigenvalues are
618			      $p$-th roots of unity.
619			\item For all $a, b \in \F_q^n$,
620			      % Paper equation label kept on the display it names.
621			      \begin{equation}\label{eq:twisted-fq}
622				      \tau^X(a)\, \tau^Z(b)
623				      = \omega^{-\tr(a \cdot b)}\, \tau^Z(b)\, \tau^X(a)\;,
624			      \end{equation}
625			      where $a \cdot b = \sum_{i=1}^n a_i b_i \in \F_q$. The case
626			      $q = p$, $n = 1$ reads
627			      \begin{equation}\label{eq:twisted-fp}
628				      \sigma^X(a)\, \sigma^Z(b)
629				      = \omega^{-ab}\, \sigma^Z(b)\, \sigma^X(a)
630				      \qquad \text{for all } a, b \in \F_p\;.
631			      \end{equation}
632		\end{enumerate}
633	\end{lemma}
634	\begin{proof}
635		\uses{def:generalized-pauli, def:subfield-trace}
636		All identities are verified on computational basis states. For the product
637		relations with $W = X$, shifting twice by $a'$ and $a$ equals shifting by
638		$a + a'$; with $W = Z$, the phases $\omega^{\tr(aj)}\omega^{\tr(a'j)}$
639		combine by $\F_q$-linearity of the trace, and the power relation follows by
640		iterating. For the scalar twisted commutation,
641		$\tau^X(a)\tau^Z(b)\ket{j} = \omega^{\tr(bj)}\ket{j + a}$, while
642		$\tau^Z(b)\tau^X(a)\ket{j} = \omega^{\tr(b(j+a))}\ket{j + a} =
643		\omega^{\tr(ab)}\,\omega^{\tr(bj)}\ket{j + a}$. The multi-qudit relation
644		follows by applying the scalar relation factor by factor and summing the
645		exponents, using $\tr(a \cdot b) = \sum_i \tr(a_i b_i)$. For $q = p$ the
646		trace is the identity map, which gives \eqref{eq:twisted-fp}.
647	\end{proof}
