673	\begin{lemma}[Fourier expansion of Pauli observables]\label{lem:pauli-observable-expansion}
674		\uses{def:generalized-pauli, def:subfield-trace}
675		For every integer $n \ge 1$, all $W \in \{X, Z\}$, and all $a \in \F_q^n$,
676		% Paper equation label kept on the display it names.
677		\begin{equation}\label{eq:pauli-obs-proj}
678			\tau^W(a) = \sum_{b \in \F_q^n} \omega^{\tr(a \cdot b)}\, \tau^W_b\;,
679		\end{equation}
680		and conversely
681		\begin{equation}\label{eq:pauli-inversion-0}
682			\E_{\ba \sim \F_q^n}\, \omega^{-\tr(\ba \cdot b)}\, \tau^W(\ba)
683			= \sum_{b' \in \F_q^n} \E_{\ba \sim \F_q^n}\,
684			\omega^{\tr(\ba \cdot (b' - b))}\, \tau^W_{b'}
685			= \tau^W_b\;.
686		\end{equation}
687	\end{lemma}
688	\begin{proof}
689		\uses{def:generalized-pauli, lem:cancellation}
690		Each $\ket{b_W}$ is an eigenvector of $\tau^W(a)$ with eigenvalue
691		$\omega^{\tr(a \cdot b)}$: for $W = Z$ this is immediate from the
692		definition, and for $W = X$ it follows from the single-qudit computation
693		$\tau^X(a)\ket{e_X} = \omega^{\tr(ae)}\ket{e_X}$, applied factor by factor.
694		Expanding $\tau^W(a)$ in the orthonormal eigenbasis
695		$\{\ket{b_W}\}_{b \in \F_q^n}$ gives the first display. For the inversion,
696		substitute the first display and exchange the order of summation; by
697		Lemma~\ref{lem:cancellation} applied with $V = \F_q^n$ (so that
698		$V^\perp = \{0\}$), the inner expectation vanishes unless $b' = b$, where
699		it equals $1$.
700	\end{proof}
